    snakeDeath: { group: "Beasts", label: "Snake dying", about: "A hiss trailing away.", plays: "An adder (a Gila monster higher; a spitting cobra, a basilisk and a great boa lower; a death worm lower still) dying." },
    crocCall: { group: "Beasts", label: "Crocodile calling", about: "An alligator's deep, rumbling growl.", plays: "A marsh crocodile (a knucker lower) setting on someone, and now and then as it goes about its business; heard up to 50 metres off." },
    crocAttack: { group: "Beasts", label: "Crocodile attacking", about: "A snake's hiss, slowed, over an alligator's growl.", plays: "A marsh crocodile (a knucker lower) striking, loudest as its blow lands." },
    crocHurt: { group: "Beasts", label: "Crocodile hurt", about: "A young caiman's distress grunt, slowed.", plays: "A marsh crocodile (a knucker lower) struck, no oftener than every 0.7 seconds." },
    crocDeath: { group: "Beasts", label: "Crocodile dying", about: "An alligator's growl, slowed, dying away.", plays: "A marsh crocodile (a knucker lower) dying." },
