    frogAttack: { group: "Beasts", label: "Frog attacking", about: "A short, deep croak.", plays: "A bog frog (a salamander higher, sizzling; a cave olm lower) striking, loudest as its blow lands." },
    frogHurt: { group: "Beasts", label: "Frog hurt", about: "A common toad's distress cry.", plays: "A bog frog (a salamander higher, sizzling; a cave olm lower) struck, no oftener than every 0.7 seconds." },
    frogDeath: { group: "Beasts", label: "Frog dying", about: "A deep croak, slowed further, fading.", plays: "A bog frog (a salamander higher, sizzling; a cave olm lower) dying." },
